    if dist_matrix is None:
        dist_matrix = get(instance, "dist", None)

    if customers is None:
        if n is not None:
            customers = [i for i in range(n) if i != depot]
        elif isinstance(demands, dict):
            customers = [k for k in demands.keys() if k != depot]
        elif coords is not None:
            customers = [i for i in range(len(coords)) if i != depot]
        elif dist_matrix is not None:
            customers = [i for i in range(len(dist_matrix)) if i != depot]
        else:
            customers = []
    customers = [c for c in as_list(customers) if c != depot]

    capacity = get(instance, "capacity", None)
    if capacity is None:
        capacity = get(instance, "vehicle_capacity", None)
    if capacity is None:
        capacity = 10 ** 18

    if isinstance(demands, dict):
        demand = lambda c: demands.get(c, 0)
    elif isinstance(demands, (list, tuple)):
        demand = lambda c: demands[c] if 0 <= c < len(demands) else 0
    else:
        demand = lambda c: 0

    def dist(i, j):
        if dist_matrix is not None:
            return dist_matrix[i][j]
        if coords is not None:
            a = coords[i]
            b = coords[j]
            dx = a[0] - b[0]
            dy = a[1] - b[1]
            return (dx * dx + dy * dy) ** 0.5
        return abs(i - j)

    def route_load(r):
        s = 0
        for x in r:
            s += demand(x)
        return s

    def route_cost(r):
        if not r:
            return 0
        s = dist(depot, r[0])
        for i in range(len(r) - 1):
            s += dist(r[i], r[i + 1])
        s += dist(r[-1], depot)
        return s

    def insertion_delta(r, c, pos):
        a = depot if pos == 0 else r[pos - 1]
        b = depot if pos == len(r) else r[pos]
        return dist(a, c) + dist(c, b) - dist(a, b)

    def best_insertion_route(routes, c):
        best_i = None
        best_pos = None
        best_delta = None
        for i, r in enumerate(routes):
            if route_load(r) + demand(c) > capacity:
                continue
            for pos in range(len(r) + 1):
                dlt = insertion_delta(r, c, pos)
                if (best_delta is None or dlt < best_delta - 1e-12 or
                    (abs(dlt - best_delta) <= 1e-12 and (i < best_i or (i == best_i and pos < best_pos)))):
                    best_delta = dlt
                    best_i = i
                    best_pos = pos
        return best_i, best_pos, best_delta

    def choose_seed(unserved):
        best = None
        best_key = None
        for c in unserved:
            key = (-demand(c), -dist(depot, c), c)
            if best_key is None or key < best_key:
                best_key = key
                best = c
        return best

    unserved = set(customers)
    routes = []

    # Constructive phase: seed by demand/distance, then cheapest feasible insertion.
    while unserved:
        seed = choose_seed(unserved)
        r = [seed]
        unserved.remove(seed)
        load = demand(seed)
        while unserved:
            best_c = None
            best_pos = None
            best_delta = None
            # Prefer customers near the current route end, but evaluate all positions.
            candidates = sorted(unserved, key=lambda x: (dist(r[-1], x), -demand(x), x))
            for c in candidates:
                dc = demand(c)
                if load + dc > capacity:
                    continue
                for pos in range(len(r) + 1):
                    dlt = insertion_delta(r, c, pos)
                    if (best_delta is None or dlt < best_delta - 1e-12 or
                        (abs(dlt - best_delta) <= 1e-12 and (c < best_c or (c == best_c and pos < best_pos)))):
                        best_c = c
                        best_pos = pos
                        best_delta = dlt
            if best_c is None:
                break
            r.insert(best_pos, best_c)
            load += demand(best_c)
            unserved.remove(best_c)
        routes.append(r)

    # Repair: if any remain (should not happen), greedily insert or create singleton routes.
    if unserved:
        for c in sorted(unserved, key=lambda x: (-demand(x), dist(depot, x), x)):
            i, pos, _ = best_insertion_route(routes, c)
            if i is None:
                routes.append([c])
            else:
                routes[i].insert(pos, c)
        unserved.clear()

    # Local search: intra-route 2-opt and relocation between routes.
    improved = True
    while improved:
        improved = False

        # Intra-route 2-opt.
        for ri in range(len(routes)):
            r = routes[ri]
            if len(r) < 4:
                continue
            best_r = r
            best_cost = route_cost(r)
            nrm = len(r)
            for i in range(nrm - 2):
                for j in range(i + 2, nrm):
                    cand = r[:i] + r[i:j + 1][::-1] + r[j + 1:]
                    cc = route_cost(cand)
                    if cc < best_cost - 1e-12 or (abs(cc - best_cost) <= 1e-12 and cand < best_r):
                        best_cost = cc
                        best_r = cand
            if best_r is not r:
                routes[ri] = best_r
                improved = True

        # Inter-route relocate / swap.
        best_move = None
        best_gain = 0
        m = len(routes)
        for i in range(m):
            ri = routes[i]
            li = route_load(ri)
            for j in range(m):
                if i == j:
                    continue
                rj = routes[j]
                lj = route_load(rj)

                # Relocate one customer from ri to rj.
                for a_idx, a in enumerate(ri):
                    da = demand(a)
                    if lj + da > capacity:
                        continue
                    ri_wo = ri[:a_idx] + ri[a_idx + 1:]
                    old_i = route_cost(ri)
                    new_i = route_cost(ri_wo) if ri_wo else 0
                    for pos in range(len(rj) + 1):
                        delta_j = insertion_delta(rj, a, pos)
                        gain = (old_i - new_i) - delta_j
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_move = ("relocate", i, j, a_idx, pos)

                # Swap customers between routes.
                for a_idx, a in enumerate(ri):
                    da = demand(a)
                    for b_idx, b in enumerate(rj):
                        db = demand(b)
                        if li - da + db > capacity or lj - db + da > capacity:
                            continue
                        ri2 = ri[:]
                        rj2 = rj[:]
                        ri2[a_idx] = b
                        rj2[b_idx] = a
                        old = route_cost(ri) + route_cost(rj)
                        new = route_cost(ri2) + route_cost(rj2)
                        gain = old - new
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_move = ("swap", i, j, a_idx, b_idx)

        if best_move is not None:
            if best_move[0] == "relocate":
                _, i, j, a_idx, pos = best_move
                a = routes[i][a_idx]
                routes[i] = routes[i][:a_idx] + routes[i][a_idx + 1:]
                routes[j].insert(pos, a)
                if not routes[i]:
                    del routes[i]
            else:
                _, i, j, a_idx, b_idx = best_move
                a = routes[i][a_idx]
                b = routes[j][b_idx]
                routes[i][a_idx] = b
                routes[j][b_idx] = a
            improved = True

    # Final cleanup: remove empty routes, ensure all customers appear exactly once by deduping.
    seen = set()
    cleaned = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c == depot or c in seen:
                continue
            if load + demand(c) <= capacity:
                nr.append(c)
                seen.add(c)
                load += demand(c)
        if nr:
            cleaned.append(nr)
    routes = cleaned

    missing = [c for c in customers if c not in seen]
    for c in missing:
        i, pos, _ = best_insertion_route(routes, c)
        if i is None:
            routes.append([c])
        else:
            routes[i].insert(pos, c)

    return routes
